<!doctype html>
<html lang="zh-CN" data-theme="light" data-palette="color">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>杨氏双缝干涉仿真</title>
    <meta http-equiv="Content-Security-Policy" content="default-src 'none'; connect-src 'none'; frame-src 'none'; object-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'">

    <style id="phy-sim-style">
        :root {
            --bg-color: #ffffff;
            --text-color: #333333;
            --panel-bg: #f5f5f5;
            --border-color: #cccccc;
            --accent-color: #0066cc;
            --modal-backdrop: rgba(0,0,0,0.55);
            --canvas-bg: #000000;
        }
        [data-theme="dark"] {
            --bg-color: #1a1a2e;
            --text-color: #e0e0e0;
            --panel-bg: #252540;
            --border-color: #444466;
            --accent-color: #5599ff;
            --modal-backdrop: rgba(0,0,0,0.8);
            --canvas-bg: #000000;
        }
        * { box-sizing: border-box; margin: 0; padding: 0; }
        html, body { height: 100%; }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Noto Sans SC", sans-serif;
            background: var(--bg-color);
            color: var(--text-color);
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }
        body[data-compact="true"] { font-size: 13px; }
        body[data-compact="true"] .panel-controls { padding: 0.6rem; gap: 0.7rem; }
        body[data-compact="true"] .visual-box { padding: 0.5rem; }

        header {
            padding: 0.6rem 1rem;
            border-bottom: 1px solid var(--border-color);
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-shrink: 0;
        }
        h1 { font-size: 1.15rem; }
        .toolbar button {
            background: var(--panel-bg);
            border: 1px solid var(--border-color);
            color: var(--text-color);
            padding: 0.35rem 0.7rem;
            cursor: pointer;
            border-radius: 4px;
            margin-left: 0.4rem;
            font-size: 0.85rem;
        }
        .toolbar button:hover { opacity: 0.8; }

        main {
            display: flex;
            flex: 1;
            overflow: hidden;
            padding: 0.8rem;
            gap: 0.8rem;
        }
        .panel-controls {
            width: 280px;
            flex-shrink: 0;
            background: var(--panel-bg);
            border: 1px solid var(--border-color);
            border-radius: 6px;
            padding: 1rem;
            display: flex;
            flex-direction: column;
            gap: 1rem;
            overflow-y: auto;
        }
        .panel-visuals {
            flex: 1;
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
            min-width: 0;
        }
        .visual-box {
            background: var(--panel-bg);
            border: 1px solid var(--border-color);
            border-radius: 6px;
            padding: 0.7rem;
            display: flex;
            flex-direction: column;
            flex: 1;
            min-height: 120px;
        }
        .box-title { font-size: 0.82rem; font-weight: 600; margin-bottom: 0.4rem; }
        .control-group { display: flex; flex-direction: column; gap: 0.25rem; }
        .label-row { display: flex; justify-content: space-between; font-size: 0.82rem; }
        input[type=range] { width: 100%; cursor: pointer; accent-color: var(--accent-color); }
        .markers-container { position: relative; height: 12px; margin-top: 2px; }
        .marker {
            position: absolute;
            width: 8px; height: 8px;
            top: 2px;
            transform: translateX(-50%);
            border-radius: 50%;
        }
        .marker.bright, .marker[data-kind="bright"] { background: var(--accent-color); }
        .marker.dark, .marker[data-kind="dark"] { background: transparent; border: 2px solid var(--accent-color); }

        .canvas-wrapper {
            flex: 1;
            position: relative;
            width: 100%;
            background: var(--canvas-bg);
            border: 1px solid var(--border-color);
            overflow: hidden;
            min-height: 80px;
        }
        .canvas-wrapper canvas { display: block; width: 100%; height: 100%; }
        #intensityCanvas:focus { outline: 2px solid var(--accent-color); outline-offset: -2px; }

        #intensity-tooltip {
            position: absolute;
            background: rgba(0,0,0,0.88);
            color: #fff;
            padding: 3px 7px;
            border-radius: 3px;
            font-size: 0.75rem;
            pointer-events: none;
            z-index: 10;
            white-space: pre;
            display: none;
            transform: translate(-50%, 0);
        }

        #principle-modal {
            position: fixed;
            inset: 0;
            background: var(--modal-backdrop);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: 1000;
            padding: 16px;
        }
        #principle-modal.open { display: flex; }
        .modal-inner {
            background: var(--bg-color);
            color: var(--text-color);
            padding: 1.5rem;
            border-radius: 8px;
            max-width: 620px;
            width: 100%;
            max-height: 88vh;
            overflow-y: auto;
            position: relative;
        }
        #modal-close-button {
            position: absolute;
            top: 0.6rem; right: 0.8rem;
            background: none; border: none;
            font-size: 1.5rem;
            cursor: pointer;
            color: var(--text-color);
            line-height: 1;
        }
        .modal-svg { width: 100%; max-height: 200px; margin: 0.8rem 0; border: 1px solid var(--border-color); border-radius: 4px; }
        .modal-note { font-size: 0.82rem; margin-top: 0.6rem; padding: 0.5rem; background: var(--panel-bg); border-radius: 4px; border: 1px solid var(--border-color); }

        @media (max-width: 768px) {
            main { flex-direction: column; overflow-y: auto; }
            .panel-controls { width: 100%; flex: none; }
            .panel-visuals { flex: none; min-height: 420px; }
        }
    </style>
</head>
<body data-compact="false">

    <header>
        <h1>杨氏双缝干涉仿真</h1>
        <div class="toolbar">
            <button id="reset-button">重置</button>
            <button id="theme-button">主题</button>
            <button id="palette-button">调色板</button>
            <button id="principle-button">原理</button>
        </div>
    </header>

    <main>
        <section class="panel-controls" aria-label="参数调控">
            <div class="box-title">参数调控</div>
            <div class="control-group">
                <div class="label-row"><label for="wavelength">波长 λ</label><output id="wavelength-output">550 nm</output></div>
                <input type="range" id="wavelength" min="380" max="750" value="550" step="1">
                <div id="wavelength-markers" class="markers-container"></div>
            </div>
            <div class="control-group">
                <div class="label-row"><label for="slitSeparation">缝间距 d</label><output id="slitSeparation-output">5000 nm</output></div>
                <input type="range" id="slitSeparation" min="1000" max="10000" value="5000" step="10">
                <div id="slitSeparation-markers" class="markers-container"></div>
            </div>
            <div class="control-group">
                <div class="label-row"><label for="slitWidth">缝宽 a</label><output id="slitWidth-output">1000 nm</output></div>
                <input type="range" id="slitWidth" min="200" max="3000" value="1000" step="10">
            </div>
            <div class="control-group">
                <div class="label-row"><label for="screenDistance">显示距离 Dsim</label><output id="screenDistance-output">50</output></div>
                <input type="range" id="screenDistance" min="1" max="100" value="50" step="1">
            </div>
            <div class="control-group">
                <div class="label-row"><label for="zoom">缩放 Z</label><output id="zoom-output">×1.0</output></div>
                <input type="range" id="zoom" min="1" max="5" value="1" step="0.1">
            </div>
        </section>

        <section class="panel-visuals">
            <div class="visual-box">
                <div class="box-title">干涉条纹图样</div>
                <div class="canvas-wrapper"><canvas id="interferenceCanvas"></canvas></div>
            </div>
            <div class="visual-box">
                <div class="box-title">归一化光强</div>
                <div class="canvas-wrapper">
                    <canvas id="intensityCanvas" tabindex="0" aria-label="归一化光强曲线，可用 Home 与方向键探测"></canvas>
                    <div id="intensity-tooltip" role="tooltip" aria-hidden="true"></div>
                </div>
            </div>
        </section>
    </main>

    <div id="principle-modal">
        <div class="modal-inner" role="dialog" aria-modal="true" aria-labelledby="modal-title">
            <button id="modal-close-button" aria-label="关闭">&times;</button>
            <h2 id="modal-title">杨氏双缝干涉原理</h2>
            <p style="margin:0.7rem 0;font-size:0.9rem;">光通过两个狭缝后发生衍射与干涉，在远处屏幕上形成明暗相间条纹。归一化光强为单缝衍射包络 sinc² 与双缝干涉因子 cos² 之积；当干涉极大恰落在衍射零点上时出现缺级。</p>
            <svg class="modal-svg" viewBox="0 0 440 200" xmlns="http://www.w3.org/2000/svg" aria-label="双缝干涉几何示意图，标注物理距离D与显示距离Dsim">
                <!-- Source -->
                <circle cx="30" cy="100" r="5" fill="currentColor"/>
                <text x="18" y="88" font-size="11" fill="currentColor">S</text>
                <!-- Double slit barrier -->
                <line x1="130" y1="10" x2="130" y2="82" stroke="currentColor" stroke-width="3"/>
                <line x1="130" y1="92" x2="130" y2="108" stroke="currentColor" stroke-width="3"/>
                <line x1="130" y1="118" x2="130" y2="190" stroke="currentColor" stroke-width="3"/>
                <text x="135" y="103" font-size="10" fill="currentColor">d</text>
                <!-- Screen -->
                <line x1="380" y1="10" x2="380" y2="190" stroke="currentColor" stroke-width="3"/>
                <text x="385" y="100" font-size="10" fill="currentColor">屏</text>
                <!-- Rays -->
                <path d="M30 100 L130 87 L380 55" stroke="currentColor" stroke-dasharray="5,3" fill="none" opacity="0.6"/>
                <path d="M30 100 L130 113 L380 55" stroke="currentColor" stroke-dasharray="5,3" fill="none" opacity="0.6"/>
                <!-- Physical D annotation -->
                <line x1="130" y1="175" x2="380" y2="175" stroke="currentColor" stroke-width="1" marker-start="url(#arrowL)" marker-end="url(#arrowR)"/>
                <defs>
                    <marker id="arrowL" markerWidth="6" markerHeight="6" refX="0" refY="3" orient="auto"><path d="M6,0 L0,3 L6,6" fill="none" stroke="currentColor" stroke-width="1"/></marker>
                    <marker id="arrowR" markerWidth="6" markerHeight="6" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="none" stroke="currentColor" stroke-width="1"/></marker>
                </defs>
                <text x="220" y="170" font-size="11" fill="currentColor" text-anchor="middle">D（物理屏距，实验几何量）</text>
                <!-- Dsim annotation -->
                <text x="220" y="195" font-size="10" fill="currentColor" text-anchor="middle" opacity="0.75">Dsim（显示距离，仅影响画布比例）</text>
                <!-- Formula -->
                <text x="30" y="20" font-size="9" fill="currentColor">I_N(η) = sinc²(πaη/λ) · cos²(πdη/λ)</text>
                <text x="30" y="33" font-size="9" fill="currentColor" opacity="0.7">η = (u − u₀) / (4·Dsim·Z)</text>
            </svg>
            <p style="font-size:0.85rem;">η 为显示坐标参数，a 为缝宽，d 为缝间距，λ 为波长。</p>
            <div class="modal-note">
                <strong>物理 D 与显示 Dsim 的区别：</strong><br>
                物理 D 是实验中双缝到屏幕的真实距离（几何量），决定实际条纹间距。本仿真中 Dsim（screenDistance 参数）与缩放 Z 仅改变画布上的显示比例（η 的映射），不改变物理光强分布与条纹级次。完整公式的满强度峰位置一般不同于理想干涉级次 m·λ/d。
            </div>
        </div>
    </div>

    <script id="phy-sim-script">
    (function(){
        'use strict';
        var VERSION='0.9.1';
        var ETA_REF=0.11;
        var KEYS=['wavelength','slitSeparation','slitWidth','screenDistance','zoom'];
        var DEFAULTS={wavelength:550,slitSeparation:5000,slitWidth:1000,screenDistance:50,zoom:1};
        var LIMITS={wavelength:[380,750],slitSeparation:[1000,10000],slitWidth:[200,3000],screenDistance:[1,100],zoom:[1,5]};

        var params={wavelength:550,slitSeparation:5000,slitWidth:1000,screenDistance:50,zoom:1};
        var theme='light',palette='color',compact=false;
        var hoverX=-1;
        var readyResolve=null;
        var readyPromise=new Promise(function(r){readyResolve=r;});

        function clamp(v,lo,hi){return v<lo?lo:(v>hi?hi:v);}

        function normalizeParams(p){
            var out={};
            for(var i=0;i<KEYS.length;i++){
                var k=KEYS[i];
                var v=(p&&typeof p[k]==='number'&&isFinite(p[k]))?p[k]:DEFAULTS[k];
                out[k]=clamp(v,LIMITS[k][0],LIMITS[k][1]);
            }
            out.slitWidth=Math.min(out.slitWidth,out.slitSeparation);
            return out;
        }

        function sinc(t){return Math.abs(t)<1e-12?1:Math.sin(t)/t;}

        function intensityAtEta(eta,p){
            p=p||params;
            if(!isFinite(eta))return 0;
            var t1=Math.PI*p.slitWidth*eta/p.wavelength;
            var t2=Math.PI*p.slitSeparation*eta/p.wavelength;
            var s=sinc(t1);
            var c=Math.cos(t2);
            return s*s*c*c;
        }

        function cssWidthOf(canvas){
            if(!canvas)return 0;
            var r=canvas.getBoundingClientRect();
            if(r.width>0)return r.width;
            var par=canvas.parentElement;
            return par?par.clientWidth:0;
        }

        function etaFromX(x,cssW,p){
            p=p||params;
            var denom=4*p.screenDistance*p.zoom;
            if(!(denom>0))denom=4*DEFAULTS.screenDistance*DEFAULTS.zoom;
            return (x-cssW/2)/denom;
        }

        function wlToRGB(wl){
            var r=0,g=0,b=0;
            if(wl>=380&&wl<440){r=-(wl-440)/60;b=1;}
            else if(wl>=440&&wl<490){g=(wl-440)/50;b=1;}
            else if(wl>=490&&wl<510){g=1;b=-(wl-510)/20;}
            else if(wl>=510&&wl<580){r=(wl-510)/70;g=1;}
            else if(wl>=580&&wl<645){r=1;g=-(wl-645)/65;}
            else if(wl>=645&&wl<=750){r=1;}
            var f=1;
            if(wl>=380&&wl<420)f=0.3+0.7*(wl-380)/40;
            else if(wl>700&&wl<=750)f=0.3+0.7*(750-wl)/50;
            return [Math.round(255*r*f),Math.round(255*g*f),Math.round(255*b*f)];
        }

        function setupCanvas(canvas){
            var dpr=window.devicePixelRatio||1;
            var par=canvas.parentElement;
            var w=par.clientWidth,h=par.clientHeight;
            canvas.width=Math.max(1,Math.round(w*dpr));
            canvas.height=Math.max(1,Math.round(h*dpr));
            canvas.style.width=w+'px';
            canvas.style.height=h+'px';
            return{w:w,h:h,dpr:dpr};
        }

        function renderPattern(){
            var canvas=document.getElementById('interferenceCanvas');
            if(!canvas)return;
            var info=setupCanvas(canvas);
            var ctx=canvas.getContext('2d');
            var w=info.w,h=info.h,dpr=info.dpr;
            if(w<=0||h<=0)return;
            ctx.setTransform(dpr,0,0,dpr,0,0);
            ctx.fillStyle='#000';
            ctx.fillRect(0,0,w,h);
            var rgb=wlToRGB(params.wavelength);
            var gamma=0.45;
            var steps=Math.max(Math.ceil(w),1);
            for(var x=0;x<steps;x++){
                var eta=etaFromX(x,w,params);
                var I=intensityAtEta(eta,params);
                var bright=Math.pow(clamp(I,0,1),gamma);
                var rr,gg,bb;
                if(palette==='grayscale'){
                    rr=gg=bb=Math.round(bright*255);
                }else{
                    rr=Math.round(rgb[0]*bright);
                    gg=Math.round(rgb[1]*bright);
                    bb=Math.round(rgb[2]*bright);
                }
                ctx.fillStyle='rgb('+rr+','+gg+','+bb+')';
                ctx.fillRect(x,0,1,h);
            }
            if(hoverX>=0&&hoverX<w){
                ctx.strokeStyle='rgba(255,255,0,0.85)';
                ctx.lineWidth=1.5;
                ctx.beginPath();
                ctx.moveTo(hoverX+0.5,0);
                ctx.lineTo(hoverX+0.5,h);
                ctx.stroke();
            }
        }

        function renderCurve(){
            var canvas=document.getElementById('intensityCanvas');
            if(!canvas)return;
            var info=setupCanvas(canvas);
            var ctx=canvas.getContext('2d');
            var w=info.w,h=info.h,dpr=info.dpr;
            if(w<=0||h<=0)return;
            ctx.setTransform(dpr,0,0,dpr,0,0);
            var bg=(theme==='dark')?'#16162a':'#fefefe';
            ctx.fillStyle=bg;
            ctx.fillRect(0,0,w,h);
            var mT=8,mB=8,pH=h-mT-mB;
            ctx.strokeStyle=(theme==='dark')?'rgba(255,255,255,0.08)':'rgba(0,0,0,0.06)';
            ctx.lineWidth=0.5;
            for(var gy=0;gy<=4;gy++){
                var yy=mT+pH*(1-gy/4);
                ctx.beginPath();ctx.moveTo(0,yy);ctx.lineTo(w,yy);ctx.stroke();
            }
            var lc=(theme==='dark')?'#5599ff':'#0055bb';
            ctx.strokeStyle=lc;
            ctx.lineWidth=1.5;
            ctx.beginPath();
            var steps=Math.max(w*2,500);
            for(var i=0;i<=steps;i++){
                var x=(i/steps)*w;
                var eta=etaFromX(x,w,params);
                var I=intensityAtEta(eta,params);
                var y=mT+pH*(1-I);
                if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);
            }
            ctx.stroke();
            if(hoverX>=0&&hoverX<w){
                ctx.strokeStyle='rgba(255,180,0,0.9)';
                ctx.lineWidth=1.5;
                ctx.setLineDash([4,3]);
                ctx.beginPath();
                ctx.moveTo(hoverX+0.5,0);
                ctx.lineTo(hoverX+0.5,h);
                ctx.stroke();
                ctx.setLineDash([]);
                var hEta=etaFromX(hoverX,w,params);
                var hI=intensityAtEta(hEta,params);
                var dy=mT+pH*(1-hI);
                ctx.fillStyle='#ff4444';
                ctx.beginPath();
                ctx.arc(hoverX,dy,4,0,Math.PI*2);
                ctx.fill();
            }
        }

        function getCriticalMarkers(p){
            p=p||params;
            var lam=p.wavelength,d=p.slitSeparation;
            var res={wavelength:[],slitSeparation:[]};
            var m,lv;
            for(m=1;m<=500;m++){
                lv=d*ETA_REF/m;
                if(lv<LIMITS.wavelength[0])break;
                if(lv<=LIMITS.wavelength[1]){
                    res.wavelength.push({kind:'bright',order:m,value:lv});
                }
            }
            for(m=0;m<=500;m++){
                lv=d*ETA_REF/(m+0.5);
                if(lv<LIMITS.wavelength[0])break;
                if(lv<=LIMITS.wavelength[1]){
                    res.wavelength.push({kind:'dark',order:m+0.5,value:lv});
                }
            }
            for(m=1;m<=1000;m++){
                lv=m*lam/ETA_REF;
                if(lv>LIMITS.slitSeparation[1])break;
                if(lv>=LIMITS.slitSeparation[0]){
                    res.slitSeparation.push({kind:'bright',order:m,value:lv});
                }
            }
            for(m=0;m<=1000;m++){
                lv=(m+0.5)*lam/ETA_REF;
                if(lv>LIMITS.slitSeparation[1])break;
                if(lv>=LIMITS.slitSeparation[0]){
                    res.slitSeparation.push({kind:'dark',order:m+0.5,value:lv});
                }
            }
            return res;
        }

        function renderMarkerContainer(id,items,lim){
            var el=document.getElementById(id);
            if(!el)return;
            el.innerHTML='';
            var mn=lim[0],mx=lim[1];
            for(var i=0;i<items.length;i++){
                var it=items[i];
                var pct=(it.value-mn)/(mx-mn)*100;
                var sp=document.createElement('span');
                sp.className='marker '+it.kind;
                sp.setAttribute('data-kind',it.kind);
                sp.style.left=pct+'%';
                sp.title=it.kind+' m='+it.order+' v='+it.value.toFixed(1);
                el.appendChild(sp);
            }
        }

        function updateMarkers(){
            var mk=getCriticalMarkers(params);
            renderMarkerContainer('wavelength-markers',mk.wavelength,LIMITS.wavelength);
            renderMarkerContainer('slitSeparation-markers',mk.slitSeparation,LIMITS.slitSeparation);
        }

        function updateOutputs(){
            var e;
            e=document.getElementById('wavelength-output');if(e)e.textContent=params.wavelength+' nm';
            e=document.getElementById('slitSeparation-output');if(e)e.textContent=params.slitSeparation+' nm';
            e=document.getElementById('slitWidth-output');if(e)e.textContent=params.slitWidth+' nm';
            e=document.getElementById('screenDistance-output');if(e)e.textContent=''+params.screenDistance;
            e=document.getElementById('zoom-output');if(e)e.textContent='×'+params.zoom.toFixed(1);
        }

        function syncInputs(){
            for(var i=0;i<KEYS.length;i++){
                var inp=document.getElementById(KEYS[i]);
                if(inp)inp.value=params[KEYS[i]];
            }
            updateOutputs();
        }

        function render(){
            renderPattern();
            renderCurve();
            updateMarkers();
        }

        function applyTheme(t){
            theme=(t==='dark')?'dark':'light';
            document.documentElement.setAttribute('data-theme',theme);
        }
        function applyPalette(p){
            palette=(p==='grayscale')?'grayscale':'color';
            document.documentElement.setAttribute('data-palette',palette);
        }
        function applyCompact(c){
            compact=!!c;
            document.body.setAttribute('data-compact',compact?'true':'false');
        }

        function readURL(){
            try{
                var sp=new URLSearchParams(window.location.search);
                var merged={};
                for(var i=0;i<KEYS.length;i++){
                    var k=KEYS[i];
                    var v=null;
                    if(sp.has(k)){
                        var pv=parseFloat(sp.get(k));
                        if(isFinite(pv))v=pv;
                    }
                    merged[k]=(v===null)?DEFAULTS[k]:v;
                }
                params=normalizeParams(merged);
                if(sp.has('theme')){
                    var t=sp.get('theme');
                    if(t==='auto')t=(window.matchMedia&&window.matchMedia('(prefers-color-scheme:dark)').matches)?'dark':'light';
                    applyTheme(t);
                }
                if(sp.has('palette'))applyPalette(sp.get('palette'));
                if(sp.has('compact'))applyCompact(sp.get('compact')==='1');
            }catch(e){}
        }

        function showTooltip(x){
            var canvas=document.getElementById('intensityCanvas');
            var tip=document.getElementById('intensity-tooltip');
            if(!canvas||!tip)return;
            var w=cssWidthOf(canvas);
            if(w<=0||x<0||x>=w){hideTooltip();return;}
            var eta=etaFromX(x,w,params);
            var I=intensityAtEta(eta,params);
            tip.textContent='η='+eta.toFixed(5)+'  I_N='+(I*100).toFixed(1)+'%';
            var lx=clamp(x,60,Math.max(60,w-60));
            tip.style.left=lx+'px';
            tip.style.top='6px';
            tip.style.display='block';
            tip.setAttribute('aria-hidden','false');
        }
        function hideTooltip(){
            var tip=document.getElementById('intensity-tooltip');
            if(tip){tip.style.display='none';tip.setAttribute('aria-hidden','true');}
        }
        function setHover(x){
            var ic=document.getElementById('intensityCanvas');
            var w=cssWidthOf(ic);
            if(x>=w||x<0)x=-1;
            hoverX=x;
            renderPattern();
            renderCurve();
            if(x>=0)showTooltip(x);else hideTooltip();
        }

        var modalOpen=false,lastFocused=null;
        function openModal(){
            var m=document.getElementById('principle-modal');
            if(!m)return;
            lastFocused=document.activeElement;
            m.classList.add('open');
            modalOpen=true;
            var cb=document.getElementById('modal-close-button');
            if(cb)cb.focus();
        }
        function closeModal(){
            var m=document.getElementById('principle-modal');
            if(!m)return;
            m.classList.remove('open');
            modalOpen=false;
            if(lastFocused&&lastFocused.focus)lastFocused.focus();
        }
        function trapTab(e){
            if(!modalOpen)return;
            var inner=document.querySelector('.modal-inner');
            if(!inner)return;
            var foc=inner.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])');
            if(!foc.length)return;
            var first=foc[0],last=foc[foc.length-1];
            if(e.key==='Tab'){
                if(e.shiftKey){
                    if(document.activeElement===first){e.preventDefault();last.focus();}
                }else{
                    if(document.activeElement===last){e.preventDefault();first.focus();}
                }
            }
        }

        function init(){
            readURL();
            syncInputs();

            for(var i=0;i<KEYS.length;i++){
                (function(k){
                    var inp=document.getElementById(k);
                    if(!inp)return;
                    inp.addEventListener('input',function(){
                        var v=parseFloat(inp.value);
                        if(!isFinite(v))v=DEFAULTS[k];
                        params[k]=clamp(v,LIMITS[k][0],LIMITS[k][1]);
                        if(k==='slitSeparation'||k==='slitWidth'){
                            params.slitWidth=Math.min(params.slitWidth,params.slitSeparation);
                            var sw=document.getElementById('slitWidth');
                            if(sw)sw.value=params.slitWidth;
                        }
                        updateOutputs();
                        render();
                    });
                })(KEYS[i]);
            }

            document.getElementById('reset-button').addEventListener('click',function(){
                params=normalizeParams({});
                syncInputs();
                render();
            });
            document.getElementById('theme-button').addEventListener('click',function(){
                applyTheme(theme==='dark'?'light':'dark');
                render();
            });
            document.getElementById('palette-button').addEventListener('click',function(){
                applyPalette(palette==='color'?'grayscale':'color');
                render();
            });
            document.getElementById('principle-button').addEventListener('click',openModal);
            document.getElementById('modal-close-button').addEventListener('click',closeModal);
            var modal=document.getElementById('principle-modal');
            modal.addEventListener('click',function(e){if(e.target===modal)closeModal();});
            document.addEventListener('keydown',function(e){
                if(e.key==='Escape'&&modalOpen){closeModal();return;}
                trapTab(e);
            });

            var ic=document.getElementById('intensityCanvas');
            ic.addEventListener('pointermove',function(e){
                var r=ic.getBoundingClientRect();
                setHover(e.clientX-r.left);
            });
            ic.addEventListener('pointerleave',function(){setHover(-1);});
            ic.addEventListener('keydown',function(e){
                var w=cssWidthOf(ic);
                if(w<=0)return;
                var cx=(hoverX>=0)?hoverX:w/2;
                if(e.key==='Home'){cx=w/2;e.preventDefault();}
                else if(e.key==='End'){cx=w-1;e.preventDefault();}
                else if(e.key==='ArrowLeft'){cx=Math.max(0,cx-2);e.preventDefault();}
                else if(e.key==='ArrowRight'){cx=Math.min(w-1,cx+2);e.preventDefault();}
                else return;
                setHover(cx);
            });
            ic.addEventListener('focus',function(){
                if(hoverX<0)setHover(cssWidthOf(ic)/2);
            });
            ic.addEventListener('blur',function(){setHover(-1);});

            var rT=null;
            window.addEventListener('resize',function(){
                if(rT)clearTimeout(rT);
                rT=setTimeout(render,60);
            });

            render();
            if(readyResolve)readyResolve(true);
        }

        window.PhySim={
            version:VERSION,
            defaults:JSON.parse(JSON.stringify(DEFAULTS)),
            limits:JSON.parse(JSON.stringify(LIMITS)),
            ready:readyPromise,
            getParams:function(){
                return{wavelength:params.wavelength,slitSeparation:params.slitSeparation,slitWidth:params.slitWidth,screenDistance:params.screenDistance,zoom:params.zoom};
            },
            setParams:function(partial){
                if(!partial||typeof partial!=='object')return;
                var merged={};
                for(var i=0;i<KEYS.length;i++){
                    var k=KEYS[i];
                    merged[k]=partial.hasOwnProperty(k)?partial[k]:params[k];
                }
                params=normalizeParams(merged);
                syncInputs();
                render();
            },
            intensityAtEta:function(eta,p){return intensityAtEta(eta,p||params);},
            getCriticalMarkers:function(p){return getCriticalMarkers(p||params);},
            render:function(){render();}
        };

        if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}
        else{init();}
    })();
    </script>
